(function(root){
 const definitions={potion:{name:'포션',icon:'🧪',description:'체력 40 회복'},charge:{name:'기술 충전제',icon:'⚡',description:'선택한 기술 PP 5 회복 · 궁극기 제외'},cleanse:{name:'상태 회복약',icon:'💧',description:'내 무기의 상태이상 해제'}};
 function parse(action){const match=/^item:(potion|cleanse|charge)(?::([0-3]))?$/.exec(action||'');return match?{id:match[1],index:match[2]===undefined?null:Number(match[2])}:null;}
 function count(state,id){return(state.items?.[id]||0)+(id==='potion'?(state.potions||0):0);}
 function reason(state,item,moves,conditions){if(!count(state,item.id))return'이 아이템을 모두 사용했어.';if(item.id==='potion'&&state.hp>=100)return'체력이 이미 가득 차 있어.';if(item.id==='cleanse'&&!conditions.list(state,'player').length)return'회복할 상태이상이 없어.';if(item.id==='charge'){const move=moves[item.index];if(!move)return'충전할 기술을 선택해 줘.';if(move.ultimate)return'궁극기는 전투당 한 번만 사용할 수 있어.';if(state.pp[item.index]>=move.pp)return'이 기술의 PP가 이미 가득 차 있어.';}return'';}
 function use(state,item,moves,conditions){state.items={potion:0,charge:0,cleanse:0,...state.items};if(item.id==='potion'&&state.potions>0)state.potions--;else state.items[item.id]--;let effect='';if(item.id==='potion'){const amount=Math.min(40,100-state.hp);state.hp+=amount;effect='체력을 '+amount+' 회복했다.';}if(item.id==='charge'){const index=item.index,amount=Math.min(5,moves[index].pp-state.pp[index]);state.pp[index]+=amount;effect=moves[index].name+'의 PP를 '+amount+' 회복했다.';}if(item.id==='cleanse'){conditions.clear(state,'player');state.playerVolatile={};effect='내 무기의 상태이상이 모두 풀렸다.';}state.message=definitions[item.id].name+(item.id==='charge'?'를':'을')+' 사용했다!\n'+effect;}
 const api={definitions,parse,count,reason,use};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.Craft.Items=api;
})(typeof window!=='undefined'?window:globalThis);
